const SIDE_LABEL = { RL: "Right/Left", F: "Frontage", SEC: "Section", S: "Side" };

function lookupPrice(block, hallcode, side, level) {
  const group = HALL_GROUP[block]?.[hallcode];
  if (!group) return null;
  const sideLabel = SIDE_LABEL[side];
  const table = PRICING[block]?.find((t) => t.hall === group && t.side === sideLabel);
  if (!table) return null;
  const row = table.rows.find((r) => String(r[0]) === String(level));
  if (!row) return null;
  return { doubleActual: row[1], singleActual: row[2], doublePromo: row[3], singlePromo: row[4] };
}

// ---- 01.07.2026–30.09.2026 Customer Promotion: Niche Special Cash Rebate (section 4.1) ----
// "40%" column = standard installment plan (company convention, always 40% down regardless of promo minimum)
// "FP" column = full payment plan
const REBATE_ELIGIBLE_BLOCKS = ["A", "B", "C", "D", "E", "F", "G", "K", "L"]; // excludes M, N, P
function getRebate(price, isDouble, plan) {
  // plan: "40" or "FP"
  if (price > 35000) return plan === "FP" ? (isDouble ? 4000 : 0) : (isDouble ? 2000 : 0);
  if (price > 25000) return plan === "FP" ? (isDouble ? 2500 : 1000) : (isDouble ? 1500 : 500);
  if (price > 15000) return plan === "FP" ? (isDouble ? 2000 : 1000) : (isDouble ? 1000 : 500);
  return 0;
}
// ---- Section 5: Limited Time Promotion - Complimentary Urn (Full Payment only) ----
const URN_VALUE = 1688; // RM per Green Crystal Urn (翡翠水晶琉璃甕)
function getUrnGift(isDouble) {
  const units = isDouble ? 2 : 1;
  return { units, value: units * URN_VALUE };
}

// ---- Standard 40% down payment + tenure rule (company convention, always 40% regardless of promo minimum) ----
function tenureForNet(net) {
  if (net < 10000) return 18;
  if (net <= 20000) return 24;
  return 36;
}
function computeInstallment(netPrice) {
  const tenure = tenureForNet(netPrice);
  const rawDP = netPrice * 0.4;
  const rawRemaining = netPrice - rawDP;
  const rawMonthly = rawRemaining / tenure;
  const roundedMonthly = Math.floor(rawMonthly / 10) * 10;
  const diff = rawMonthly - roundedMonthly;
  const finalDP = rawDP + diff * tenure;
  return { tenure, downPayment: finalDP, monthly: roundedMonthly };
}

function isActive(promo) {
  const s = new Date(promo.start);
  const e = new Date(promo.end);
  return TODAY >= s && TODAY <= e;
}
const CURRENT_PROMO = { name: "Q3 2026 Customer Promotion", start: "2026-07-01", end: "2026-09-30" };

