function SingleQuoteView({ prefill }) {
  const [code, setCode] = useState(prefill?.code || "");
  const [block, setBlock] = useState(prefill?.block || "A");
  const [hallcode, setHallcode] = useState(prefill?.hallcode || "");
  const [side, setSide] = useState(prefill?.side || "");
  const [level, setLevel] = useState(prefill?.level || "");
  const [isDouble, setIsDouble] = useState(true);
  const [showQuote, setShowQuote] = useState(false);

  // Skip auto-fill on initial mount if a prefill already fully specified the lot
  // (fixes bug: typing-based lookup was overwriting the prefill hall with the
  // first duplicate-code match elsewhere in the same block, e.g. Block L codes
  // that repeat across multiple Halls).
  const skippedPrefillAutoFill = useRef(false);
  const [ambiguousCode, setAmbiguousCode] = useState(false);

  useEffect(() => {
    if (!skippedPrefillAutoFill.current && prefill?.hallcode && code === prefill.code) {
      skippedPrefillAutoFill.current = true;
      return;
    }
    skippedPrefillAutoFill.current = true;

    if (!code.trim()) { setAmbiguousCode(false); return; }
    const matches = AVAIL.filter((r) => r.code.toLowerCase() === code.trim().toLowerCase() && (!block || r.block === block));
    setAmbiguousCode(matches.length > 1);
    const hit = matches[0];
    if (hit) {
      setBlock(hit.block); setHallcode(hit.hallcode); setSide(hit.side); setLevel(hit.level);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [code]);

  const hallOptions = Object.keys(HALL_GROUP[block] || {});
  useEffect(() => {
    if (!hallOptions.includes(hallcode)) { setHallcode(hallOptions[0] || ""); setSide(""); setLevel(""); }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [block]);

  const priceInfo = hallcode && side && level ? lookupPrice(block, hallcode, side, level) : null;
  // Actual Price is shown for reference only. Every calculation from here on
  // (rebate tier, net price, down payment, installment) always runs off the
  // Promo Price column in the price list, per company policy.
  const actualPrice = priceInfo ? (isDouble ? priceInfo.doubleActual : priceInfo.singleActual) : null;
  const basePrice = priceInfo ? (isDouble ? priceInfo.doublePromo : priceInfo.singlePromo) : null;

  const eligible = REBATE_ELIGIBLE_BLOCKS.includes(block);
  const rebate40 = basePrice != null && eligible ? getRebate(basePrice, isDouble, "40") : 0;
  const netPrice40 = basePrice != null ? basePrice - rebate40 : null;
  const plan = netPrice40 != null ? computeInstallment(netPrice40) : null;

  const rebateFP = basePrice != null && eligible ? getRebate(basePrice, isDouble, "FP") : 0;
  const netPriceFP = basePrice != null ? basePrice - rebateFP : null;
  const urnGift = getUrnGift(isDouble);

  return (
    <div className="px-4 pt-4 pb-24">
      <div className="flex items-center gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        <Info size={13} /> 促销:{CURRENT_PROMO.name}({fmtDate(CURRENT_PROMO.start)}–{fmtDate(CURRENT_PROMO.end)}),头期固定按 40% 算
      </div>

      <TextInput placeholder="输入福位编号自动带入 (可选)" value={code} onChange={(e) => setCode(e.target.value)} className="mb-1" />
      {ambiguousCode && (
        <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 11.5, marginTop: 2, marginBottom: 10 }}>
          ⚠️ 这个编号在这个 Block 里出现在多个 Hall,系统按顺序选了其中一个,请手动核对/切换正确的 Hall
        </p>
      )}
      {!ambiguousCode && <div className="mb-3" />}

      <div className="grid grid-cols-2 gap-2 mb-3">
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Block</div>
          <Select value={block} onChange={(e) => setBlock(e.target.value)}>
            {BLOCKS.map((b) => <option key={b} value={b}>{b} 座</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Hall</div>
          <Select value={hallcode} onChange={(e) => { setHallcode(e.target.value); setSide(""); }}>
            <option value="">选择</option>
            {hallOptions.map((h) => <option key={h} value={h}>{h}</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>朝向 Side</div>
          <Select value={side} onChange={(e) => setSide(e.target.value)}>
            <option value="">选择</option>
            <option value="RL">Right / Left</option>
            <option value="F">Frontage</option>
            <option value="SEC">Section (L 座专用)</option>
            <option value="S">Side (N 座专用)</option>
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>楼层 Level</div>
          <TextInput placeholder="e.g. 10, 3A, 08-138" value={level} onChange={(e) => setLevel(e.target.value)} />
        </div>
      </div>

      <div className="flex gap-2 mb-4">
        <button onClick={() => setIsDouble(true)} className="flex-1 rounded-xl px-3 py-2 text-sm"
          style={{ background: isDouble ? COLOR.gold : COLOR.panel2, color: isDouble ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
          双人 Double
        </button>
        <button onClick={() => setIsDouble(false)} className="flex-1 rounded-xl px-3 py-2 text-sm"
          style={{ background: !isDouble ? COLOR.gold : COLOR.panel2, color: !isDouble ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
          单人 Single
        </button>
      </div>

      {hallcode && side && level && !priceInfo && (
        <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 13 }}>
          价格资料库里没有这个组合(Block {block} {hallcode} 目前没有价格表)— 请跟主管确认最新价格。
        </p>
      )}

      {basePrice != null && (
        <>
          <Card style={{ marginTop: 4, border: `1px solid ${COLOR.gold}55` }}>
            <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>
              {block} 座 {hallcode} · {side === "F" ? "Frontage" : side === "SEC" ? "Section" : side === "S" ? "Side" : "Right/Left"} · Level {level} · {isDouble ? "双人" : "单人"}
            </div>
            <Row label="原价 Actual Price" value={money(actualPrice)} />
            <Row label="促销价 Promo Price(以此价格计算)" value={money(basePrice)} bold accent />
          </Card>

          <div className="mt-3">
            <MiniFloorPlan block={block} side={side} hallcode={hallcode} />
          </div>

          {plan && (
            <Card style={{ marginTop: 12, border: `1px solid ${COLOR.gold}55` }}>
              <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>方案 A · 分期付款(标准 40% 头期)</div>
              <Row label={eligible ? "促销现金回扣 Cash Rebate (40%)" : "此 Block 不适用现金回扣"} value={rebate40 ? "-" + money(rebate40) : "—"} />
              <Row label="净价 Net Price" value={money(netPrice40)} bold />
              <Row label="头期 Down Payment(整数月供后补回)" value={money(plan.downPayment)} bold accent />
              <Row label="供期 Tenure" value={`${plan.tenure} 个月`} />
              <Row label="每月供款 Monthly" value={money(plan.monthly) + " / 月"} bold />
              <div className="mt-2 pt-2 text-[11px]" style={{ borderTop: `1px solid ${COLOR.line}`, color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
                供期按净价定:低于 RM10,000 = 18 个月;RM10,000–20,000 = 24 个月;高于 RM20,000 = 36 个月
              </div>
            </Card>
          )}

          {netPriceFP != null && (
            <Card style={{ marginTop: 12, border: `1px solid ${COLOR.green}55` }}>
              <div style={{ color: COLOR.green, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>方案 B · 全额付款 Full Payment (FP)</div>
              <Row label={eligible ? "促销现金回扣 Cash Rebate (FP)" : "此 Block 不适用现金回扣"} value={rebateFP ? "-" + money(rebateFP) : "—"} />
              <Row label="全款净价 Net Cash Price" value={money(netPriceFP)} bold accent />
              <Row label="附送翡翠水晶琉璃甕 Complimentary Urn" value={`${urnGift.units} 个 (价值 ${money(urnGift.value)})`} bold />
              <div className="mt-2 pt-2 text-[11px]" style={{ borderTop: `1px solid ${COLOR.line}`, color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
                单人送 1 个,双人送 2 个,每个价值 RM1,688。只限全额付款的 Pre-need / Immigration 个案。
              </div>
            </Card>
          )}

          <Btn onClick={() => setShowQuote(true)} className="w-full mt-4" variant="ghost">生成报价单预览 Generate Quotation</Btn>

          {showQuote && (
            <Card style={{ marginTop: 12, background: "#fff" }}>
              <div className="flex items-center gap-2 mb-3">
                <AlphaMark size={22} />
                <span style={{ fontFamily: FONT_DISPLAY, fontWeight: 700, color: "#141414" }}>甲板山庄 Jiangnan Villa — Quotation</span>
              </div>
              <div style={{ fontFamily: FONT_BODY, fontSize: 12.5, color: "#333", lineHeight: 1.9 }}>
                <div><b>福位 Niche:</b> {block} 座 {hallcode} {code && `(${code})`} · Level {level} · {isDouble ? "双人 Double" : "单人 Single"}</div>
                <div><b>原价 Actual Price:</b> {money(actualPrice)}</div>
                <div><b>促销价 Promo Price(计算基础):</b> {money(basePrice)}</div>
                {plan && (
                  <>
                    <div className="mt-1"><b>— 方案 A 分期 40% —</b></div>
                    <div>现金回扣: {rebate40 ? money(rebate40) : "不适用"} · 净价: {money(netPrice40)}</div>
                    <div>头期: {money(plan.downPayment)} · 供期: {plan.tenure} 个月 · 月供: {money(plan.monthly)}/月</div>
                  </>
                )}
                <div className="mt-1"><b>— 方案 B 全额付款 FP —</b></div>
                <div>现金回扣: {rebateFP ? money(rebateFP) : "不适用"} · 全款净价: {money(netPriceFP)}</div>
                <div>附送翡翠水晶琉璃甕 {urnGift.units} 个(价值 {money(urnGift.value)})</div>
                <div className="mt-2 text-[11px]" style={{ color: "#888" }}>促销有效期至 {fmtDate(CURRENT_PROMO.end)},价格与促销以公司最新公布为准。</div>
              </div>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

function BurialPlotView() {
  const [zoneKey, setZoneKey] = useState(BURIAL_ZONES[0].key);
  const [categoryKey, setCategoryKey] = useState(BURIAL_ZONES[0].categories[0].key);
  const [tierKey, setTierKey] = useState("");

  const zone = BURIAL_ZONES.find((z) => z.key === zoneKey) || BURIAL_ZONES[0];
  const category = zone.categories.find((c) => c.key === categoryKey) || zone.categories[0];
  const tiers = burialRebateTiers(zone);
  const activeTierKey = tiers.includes(tierKey) ? tierKey : tiers[0];

  const result = computeBurialTier(zone, category.promo, activeTierKey);

  const handleZoneChange = (key) => {
    const nextZone = BURIAL_ZONES.find((z) => z.key === key) || BURIAL_ZONES[0];
    setZoneKey(key);
    setCategoryKey(nextZone.categories[0].key);
    setTierKey(burialRebateTiers(nextZone)[0]);
  };

  return (
    <div className="px-4 pt-4 pb-24">
      <div className="flex items-center gap-1.5 mb-3 text-xs" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY }}>
        <Info size={13} /> 土葬各 Zone 价格来自公司价格表;计算一律以「促销价 Promo Price」为准,原价只作参考
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>Zone</div>
          <Select value={zone.key} onChange={(e) => handleZoneChange(e.target.value)}>
            {BURIAL_ZONES.map((z) => <option key={z.key} value={z.key}>{z.label}</option>)}
          </Select>
        </div>
        <div>
          <div style={{ color: COLOR.inkSoft, fontSize: 11, fontFamily: FONT_BODY, marginBottom: 4 }}>类别 Category</div>
          <Select value={category.key} onChange={(e) => setCategoryKey(e.target.value)}>
            {zone.categories.map((c) => <option key={c.key} value={c.key}>{c.label}</option>)}
          </Select>
        </div>
      </div>

      {category.note && (
        <p style={{ color: COLOR.orange, fontFamily: FONT_BODY, fontSize: 11.5, marginBottom: 10 }}>⚠️ {category.note}</p>
      )}

      <Card style={{ marginTop: 4, border: `1px solid ${COLOR.gold}55` }}>
        <div style={{ color: COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>
          {zone.label} · {category.label}
        </div>
        <Row label="面积 Size" value={zone.size} />
        <Row label="用位 No. of Interment" value={`${zone.pax} 位`} />
        <Row label="原价 Actual Price" value={money(category.actual)} />
        <Row label="促销价 Promo Price(以此价格计算)" value={money(category.promo)} bold accent />
        <Row label="价格生效日 WEF" value={zone.wef} />
      </Card>

      <div className="flex gap-2 mt-3 mb-1 flex-wrap">
        {tiers.map((t) => (
          <button key={t} onClick={() => setTierKey(t)} className="rounded-xl px-3 py-2 text-sm"
            style={{ background: activeTierKey === t ? COLOR.gold : COLOR.panel2, color: activeTierKey === t ? "#161512" : COLOR.inkSoft, fontFamily: FONT_BODY, fontWeight: 600 }}>
            {BURIAL_TIER_LABEL[t] || t}
          </button>
        ))}
      </div>

      <Card style={{ marginTop: 8, border: `1px solid ${result.isFP ? COLOR.green : COLOR.gold}55` }}>
        <div style={{ color: result.isFP ? COLOR.green : COLOR.gold, fontFamily: FONT_BODY, fontWeight: 700, fontSize: 12 }}>
          {result.isFP ? "全额付款 Full Payment" : `${BURIAL_TIER_LABEL[result.tierKey] || result.tierKey} 分期方案`}
        </div>
        <Row label={zone.rebate ? "促销现金回扣 Cash Rebate" : "此 Zone 暂无现金回扣促销资料"} value={result.rebate ? "-" + money(result.rebate) : "—"} />
        <Row label="净价 Net Price" value={money(result.netPrice)} bold />
        {result.isFP ? (
          <Row label="全款金额 Full Payment Amount" value={money(result.downPayment)} bold accent />
        ) : (
          <>
            <Row label="头期 Down Payment" value={money(result.downPayment)} bold accent />
            <Row label="供期 Tenure" value={`${result.tenure} 个月`} />
            <Row label="每月供款 Monthly" value={money(result.monthly) + " / 月"} bold />
          </>
        )}
      </Card>

      <div className="mt-3 text-[11px]" style={{ color: COLOR.inkSoft, fontFamily: FONT_BODY, lineHeight: 1.7 }}>
        Booking fee RM500 起(Zone IZ 为 RM1,000)· Sheng-Ji 附加费一般 RM1,200/次(Zone DA 为 RM650)。价格与促销以公司最新公布为准。
        此计算器不含逐格查询——各 Zone 楼层图上实际哪个柱位还空置,请与主管确认后再报价。
      </div>
    </div>
  );
}

